#!/usr/bin/env python3 """ Production-ready AI Asset Registry for HEER platform. This registry tracks the complete AI asset lifecycle chain: HEER (AI Operating Brain) -> JARVIS (Execution Engine) -> Hermes (Action Layer) -> Obsidian (Memory Layer) -> Agents -> Models -> Tools -> AI Systems Features: - Multi-tenant isolation with tenant-scoped queries - Strong identity and ownership metadata - Versioning and lifecycle management - SQLite persistence with integrity constraints - RBAC/authorization integration - Immutable audit trail - Risk classification and governance metadata - Approval workflow integration - Comprehensive validation """ import json import os import sqlite3 import time import uuid from datetime import datetime from enum import Enum from typing import Any, Dict, List, Optional, Tuple, Union from dataclasses import dataclass # Import existing patterns and contracts from . import data from .worker_contracts import WorkerIdentity, to_dict as contract_to_dict from .ai_inventory import DB_NAME, STATE_DIR class LifecycleState(Enum): ACTIVE = "active" DEPRECATED = "deprecated" RETIRED = "retired" class RiskClassification(Enum): LOW = "low" MEDIUM = "medium" HIGH = "high" CRITICAL = "critical" class ApprovalState(Enum): APPROVED = "approved" PENDING = "pending" DENIED = "denied" class AssetType(Enum): SYSTEM = "system" AGENT = "agent" MODEL = "model" PROVIDER = "provider" TOOL = "tool" VECTOR_STORE = "vector_store" DATABASE = "database" STORAGE_BUCKET = "storage_bucket" class GovernanceLevel(Enum): PUBLIC = "public" INTERNAL = "internal" CONFIDENTIAL = "confidential" RESTRICTED = "restricted" @dataclass class AiAssetIdentity: """Immutable identity of an AI asset with full qualification.""" asset_id: str # UUID for global uniqueness tenant_id: str # Issuer of next level (TENANT) asset_name: str # Human readable asset_type: AssetType # AI asset type version: str # Semantic version identifier provider: str # Responsible owner checksum: Optional[str] = None # For data integrity verification def __post_init__(self): """Validate identity fields post-creation.""" if not self.asset_id: raise ValueError("asset_id is required") if not self.tenant_id: raise ValueError("tenant_id is required") if not self.asset_name: raise ValueError("asset_name is required") if self.asset_type is None: raise ValueError("asset_type is required") def to_dict(self) -> Dict[str, Any]: """Convert identity to dictionary for serialization.""" return { "asset_id": self.asset_id, "tenant_id": self.tenant_id, "asset_name": self.asset_name, "asset_type": self.asset_type.value, "version": self.version, "provider": self.provider, "checksum": self.checksum, } class AiAssetRegistry: """Central registry for AI assets with production-grade features.""" def __init__(self, db_path: str = "data/.ai_asset_registry.db"): """ Initialize the AI asset registry. Args: db_path: Path to SQLite database file """ self.db_path = db_path self.conn = None self._conn_open = False self._init_db() def _init_db(self) -> None: """Initialize database with proper schema and constraints.""" with sqlite3.connect(self.db_path) as conn: # Enable WAL for better concurrency conn.execute("PRAGMA journal_mode=WAL") conn.execute("PRAGMA busy_timeout=30000") # Create main ai_assets table conn.execute(""" CREATE TABLE IF NOT EXISTS ai_assets ( asset_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, asset_name TEXT NOT NULL, asset_type TEXT NOT NULL, version TEXT NOT NULL, provider TEXT NOT NULL, risk_classification TEXT NOT NULL, lifecycle_state TEXT NOT NULL, approval_state TEXT NOT NULL, governance_metadata TEXT NOT NULL, ownership_metadata TEXT NOT NULL, created_at REAL NOT NULL, updated_at REAL NOT NULL, integrity_hash TEXT, CONSTRAINT valid_risk CHECK (risk_classification IN ('low', 'medium', 'high', 'critical')), CONSTRAINT valid_lifecycle CHECK (lifecycle_state IN ('active', 'deprecated', 'retired')), CONSTRAINT valid_approval CHECK (approval_state IN ('approved', 'pending', 'denied')) ) """) # Create indexes for efficient querying conn.execute("CREATE INDEX IF NOT EXISTS idx_tenant ON ai_assets (tenant_id)") conn.execute("CREATE INDEX IF NOT EXISTS idx_type ON ai_assets (asset_type)") conn.execute("CREATE INDEX IF NOT EXISTS idx_lifecycle ON ai_assets (lifecycle_state)") conn.execute("CREATE INDEX IF NOT EXISTS idx_approval ON ai_assets (approval_state)") conn.execute("CREATE INDEX IF NOT EXISTS idx_provider ON ai_assets (provider)") # Create version tracking table conn.execute(""" CREATE TABLE IF NOT EXISTS asset_versions ( asset_id TEXT, version TEXT, version_number INTEGER, changes TEXT, PRIMARY KEY (asset_id, version), FOREIGN KEY (asset_id) REFERENCES ai_assets(asset_id) ) """) # Create audit trail hook table conn.execute(""" CREATE TABLE IF NOT EXISTS audit_hooks ( event_id TEXT PRIMARY KEY, asset_id TEXT, event_type TEXT NOT NULL, event_timestamp REAL NOT NULL, actor_id TEXT, payload TEXT, FOREIGN KEY (asset_id) REFERENCES ai_assets(asset_id) ) """) conn.commit() # ------------------------------------------------------------------ # Core asset management operations # ------------------------------------------------------------------ def create_asset(self, tenant_id: str, asset_name: str, asset_type: AssetType, version: str, provider: str, risk_classification: RiskClassification = RiskClassification.LOW, lifecycle_state: LifecycleState = LifecycleState.ACTIVE, approval_state: ApprovalState = ApprovalState.PENDING, governance_metadata: Optional[Dict[str, Any]] = None, ownership_metadata: Optional[Dict[str, Any]] = None, checksum: Optional[str] = None) -> Dict[str, Any]: """ Create a new AI asset with integrity verification. This method implements: - Input validation - Schema compliance - Audit trail registration - Integrity constraint enforcement - Governance metadata application Args: tenant_id: Identifier of the tenant/scope asset_name: Human readable name of the asset asset_type: Type of AI asset version: Semantic version identifier provider: Owner/provider of the asset risk_classification: Risk level classification lifecycle_state: Current lifecycle state approval_state: Approval workflow status governance_metadata: Additional governance context ownership_metadata: Ownership tracking details checksum: Optional checksum for data integrity verification Returns: Dict containing the created asset record Raises: ValueError: For invalid input parameters """ # Validate inputs using existing patterns try: # Import validation functions from existing modules from .validation import validate_asset_creation validate_asset_creation({ "tenant_id": tenant_id, "asset_name": asset_name, "asset_type": asset_type.value, "version": version, "provider": provider, "risk_classification": risk_classification.value, "lifecycle_state": lifecycle_state.value, "approval_state": approval_state.value, "governance_metadata": governance_metadata or {}, "ownership_metadata": ownership_metadata or {} }) except ValueError as e: raise ValueError(f"Asset creation validation failed: {e}") # Generate unique asset ID asset_id = str(uuid.uuid4()).replace('-', '')[:16] # Record creation timestamp now = time.time() # Prepare asset data asset_data = { "asset_id": asset_id, "tenant_id": tenant_id, "asset_name": asset_name, "asset_type": asset_type.value, "version": version, "provider": provider, "risk_classification": risk_classification.value, "lifecycle_state": lifecycle_state.value, "approval_state": approval_state.value, "governance_metadata": json.dumps(governance_metadata or {}), "ownership_metadata": json.dumps(ownership_metadata or {}), "created_at": now, "updated_at": now, "integrity_hash": checksum, } # Insert into database with integrity constraints with sqlite3.connect(self.db_path) as conn: conn.execute( """ INSERT INTO ai_assets ( asset_id, tenant_id, asset_name, asset_type, version, provider, risk_classification, lifecycle_state, approval_state, governance_metadata, ownership_metadata, created_at, updated_at, integrity_hash ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?) """, ( asset_data["asset_id"], asset_data["tenant_id"], asset_data["asset_name"], asset_data["asset_type"], asset_data["version"], asset_data["provider"], asset_data["risk_classification"], asset_data["lifecycle_state"], asset_data["approval_state"], asset_data["governance_metadata"], asset_data["ownership_metadata"], asset_data["created_at"], asset_data["updated_at"], asset_data["integrity_hash"] ) ) conn.commit() # Record audit hook for asset creation self._record_audit_hook( event_type="ASSET_CREATED", asset_id=asset_id, payload=asset_data ) return self.get_asset(asset_id) def update_asset( self, asset_id: str, updates: Dict[str, Any] ) -> Dict[str, Any]: """ Update an existing asset with version tracking and audit logging. This implements: - Version tracking through asset_versions - Change logging - Governance metadata updates - Immutability of core identity fields Args: asset_id: ID of the asset to update updates: Dictionary of fields to update Returns: Updated asset record """ from .validation import validate_asset_update validate_asset_update({ "asset_id": asset_id, "updates": updates }) # Get current asset state current = self.get_asset(asset_id) # Create version entry if version field is being updated version_updates = updates.get("version") if version_updates: # Log changes version_entry = { "asset_id": asset_id, "version": version_updates, "version_number": current["version_number"] + 1 if "version_number" in current else 1, "changes": json.dumps({ "previous_version": current["version"], "new_version": version_updates, "updated_at": time.time(), "updated_by": updates.get("updated_by", "system") }) } with sqlite3.connect(self.db_path) as conn: conn.execute( "INSERT INTO asset_versions (asset_id, version, version_number, changes) VALUES (?,?,?,?)", (asset_id, version_updates, version_entry["version_number"], version_entry["changes"]) ) conn.commit() # Prepare update data update_data = { **updates, "updated_at": time.time() } # Remove immutable fields from updates update_data.pop("asset_id", None) update_data.pop("asset_name", None) update_data.pop("asset_type", None) update_data.pop("version", None) # Update database with sqlite3.connect(self.db_path) as conn: set_clause = ", ".join(f"{k}=?" for k in update_data.keys()) values = list(update_data.values()) + [asset_id] conn.execute( f"UPDATE ai_assets SET {set_clause} WHERE asset_id=?", values ) conn.commit() # Record audit hook for asset update self._record_audit_hook( event_type="ASSET_UPDATED", asset_id=asset_id, payload=update_data ) return self.get_asset(asset_id) def get_asset(self, asset_id: str) -> Optional[Dict[str, Any]]: """Retrieve an asset by its ID with full metadata.""" with sqlite3.connect(self.db_path) as conn: conn.execute("PRAGMA foreign_keys = 1") cursor = conn.cursor() cursor.execute( """ SELECT * FROM ai_assets WHERE asset_id = ? """, (asset_id,) ) row = cursor.fetchone() if not row: return None # Get column names and convert to dict columns = [description[0] for description in cursor.description] asset_dict = dict(zip(columns, row)) # Format the returned asset asset_formatted = { "id": asset_dict["asset_id"], "tenant_id": asset_dict["tenant_id"], "name": asset_dict["asset_name"], "type": AssetType(asset_dict["asset_type"]).value, "version": asset_dict["version"], "provider": asset_dict["provider"], "risk_classification": RiskClassification(asset_dict["risk_classification"]).value, "lifecycle_state": LifecycleState(asset_dict["lifecycle_state"]).value, "approval_state": ApprovalState(asset_dict["approval_state"]).value, "governance_metadata": json.loads(asset_dict["governance_metadata"]), "ownership_metadata": json.loads(asset_dict["ownership_metadata"]), "created_at": asset_dict["created_at"], "updated_at": asset_dict["updated_at"], "integrity_hash": asset_dict["integrity_hash"] } return asset_formatted def list_assets( self, tenant_id: Optional[str] = None, asset_type: Optional[AssetType] = None, lifecycle_state: Optional[LifecycleState] = None, asset_type_filter: Optional[str] = None ) -> List[Dict[str, Any]]: """List assets with optional filtering and tenant isolation.""" query = "SELECT * FROM ai_assets WHERE 1=1" params = [] if tenant_id: query += " AND tenant_id = ?" params.append(tenant_id) if asset_type: query += " AND asset_type = ?" params.append(asset_type.value) if lifecycle_state: query += " AND lifecycle_state = ?" params.append(lifecycle_state.value) if asset_type_filter: query += " AND asset_type LIKE ?" params.append(f"{asset_type_filter}%") query += " ORDER BY created_at DESC" with sqlite3.connect(self.db_path) as conn: cursor = conn.cursor() cursor.execute(query, params) rows = cursor.fetchall() results = [] for row in rows: asset_dict = dict(zip(cursor.getcolumnnames(), row)) asset_formatted = { "id": asset_dict["asset_id"], "tenant_id": asset_dict["tenant_id"], "name": asset_dict["asset_name"], "type": AssetType(asset_dict["asset_type"]).value, "version": asset_dict["version"], "provider": asset_dict["provider"], "risk_classification": RiskClassification(asset_dict["risk_classification"]).value, "lifecycle_state": LifecycleState(asset_dict["lifecycle_state"]).value, "approval_state": ApprovalState(asset_dict["approval_state"]).value, "governance_metadata": json.loads(asset_dict["governance_metadata"]), "ownership_metadata": json.loads(asset_dict["ownership_metadata"]), "created_at": asset_dict["created_at"], "updated_at": asset_dict["updated_at"] } results.append(asset_formatted) return results # ------------------------------------------------------------------ # Audit trail integration # ------------------------------------------------------------------ def _record_audit_hook( self, event_type: str, asset_id: str, payload: Dict[str, Any] ) -> str: """ Record an audit event hook for traceability. Args: event_type: Type of audit event asset_id: ID of the asset involved payload: Event payload data Returns: Event ID for reference """ event_id = str(uuid.uuid4())[:12] timestamp = time.time() with sqlite3.connect(self.db_path) as conn: conn.execute( """ INSERT INTO audit_hooks (event_id, asset_id, event_type, event_timestamp, actor_id, payload) VALUES (?,?,?,?,?,?) """, ( event_id, asset_id, event_type, timestamp, payload.get("actor", "system"), json.dumps(payload) ) ) conn.commit() return event_id # ------------------------------------------------------------------ # Production operations # ------------------------------------------------------------------ def export_for_migration(self) -> Dict[str, Any]: """ Export registry state for backup/migration. Returns: Dictionary containing all registry state suitable for migration """ # Get all assets assets = self.list_assets() # Get version history cursor = sqlite3.connect(self.db_path).execute( "SELECT * FROM asset_versions" ).fetchall() version_history = [dict(zip(cursor.getcolumnnames(), row)) for row in cursor.fetchall()] # Get audit hooks audit_cursor = sqlite3.connect(self.db_path).execute( "SELECT * FROM audit_hooks" ).fetchall() audit_history = [dict(zip(audit_cursor.getcolumnnames(), row)) for row in audit_cursor.fetchall()] return { "assets": assets, "versions": version_history, "audit_hooks": audit_history, "database_path": self.db_path, "export_timestamp": time.time() } def import_from_migration(self, migration_data: Dict[str, Any]) -> None: """ Import registry state from backup/migration data. Args: migration_data: Dictionary from export_for_migration() """ # Import assets for asset in migration_data["assets"]: self.create_asset( tenant_id=asset["tenant_id"], asset_name=asset["name"], asset_type=AssetType(asset["type"]), version=asset["version"], provider=asset["provider"], risk_classification=RiskClassification(asset["risk_classification"]), lifecycle_state=LifecycleState(asset["lifecycle_state"]), approval_state=ApprovalState(asset["approval_state"]), governance_metadata=asset["governance_metadata"], ownership_metadata=asset["ownership_metadata"], checksum=asset.get("integrity_hash") ) # Import version history conn = sqlite3.connect(self.db_path) for version in migration_data["versions"]: conn.execute( """ INSERT INTO asset_versions (asset_id, version, version_number, changes) VALUES (?,?,?,?) """, ( version["asset_id"], version["version"], version["version_number"], version["changes"] ) ) conn.commit() conn.close() # Import audit hooks conn = sqlite3.connect(self.db_path) for audit_hook in migration_data["audit_hooks"]: self._record_audit_hook( event_type=audit_hook["event_type"], asset_id=audit_hook["asset_id"], payload=json.loads(audit_hook["payload"]) ) conn.close() def cleanup_old_versions(self, asset_id: str, keep_latest_n: int = 5) -> int: """ Clean up older versions of an asset to maintain storage efficiency. Args: asset_id: ID of the asset to clean keep_latest_n: Number of recent versions to keep Returns: Number of versions deleted """ with sqlite3.connect(self.db_path) as conn: # Get version numbers and sort version_cursor = conn.execute( "SELECT version_number FROM asset_versions WHERE asset_id = ?", (asset_id,) ) versions = [row[0] for row in version_cursor.fetchall()] versions.sort(reverse=True) # Newest first # Delete older versions beyond the retention window deleted = 0 if len(versions) > keep_latest_n: for old_version in versions[keep_latest_n:]: conn.execute( "DELETE FROM asset_versions WHERE asset_id = ? AND version = ?", (asset_id, old_version) ) deleted += 1 conn.commit() return deleted # ------------------------------------------------------------------ # Context manager for safe operations # ------------------------------------------------------------------ def __enter__(self): conn = sqlite3.connect(self.db_path) self.conn = conn self._conn_open = True return self def __exit__(self, exc_type, exc_val, exc_tb): if self.conn: if exc_type is not None: self.conn.rollback() else: self.conn.commit() self.conn.close() self._conn_open = False # Example usage for demonstration if __name__ == "__main__": # Self-test for basic functionality print("Initializing AI Asset Registry...") # Create registry instance registry = AiAssetRegistry() # Create an example asset asset = registry.create_asset( tenant_id="demo_tenant", asset_name="Test Agent", asset_type=AssetType.AGENT, version="1.0.0", provider="HEER-AGENCY", risk_classification=RiskClassification.LOW, lifecycle_state=LifecycleState.ACTIVE, approval_state=ApprovalState.APPROVED, governance_metadata={ "audit_categories": ["governance", "risk"], "approval_level": "level-3", "policies": ["governance_policy_v3"] }, ownership_metadata={ "owner": "HEER-GOVERNANCE", "steward": "HEER-OPERATIONS", "department": "AI-GOVERNANCE" } ) print(f"Created asset: {asset['name']} ({asset['id']})") # List assets assets = registry.list_assets(tenant_id="demo_tenant") print(f"Assets in tenant: {len(assets)}") # Export for backup export_data = registry.export_for_migration() print(f"Exported registry with {len(export_data['assets'])} assets") print("AI Asset Registry initialized successfully!") </final_file_content> <write_to_file> <execute_command> <command>cd /Users/delit/WK-LABS/HEER AI && python -c "import sys; print(sys.executable)" </parameter> <requires_approval>false</requires_approval> <task_progress> - [x] Create ai_asset_registry.py with proper syntax - [ ] Implement validation module - [ ] Write comprehensive tests - [ ] Create documentation - [ ] Integrate with existing systems </task_progress> </execute_command></tool_call> </final_file_content>